package net.minecraft.world.entity; import java.util.UUID; public class Entity {public net.minecraft.world.phys.Vec3 position=net.minecraft.world.phys.Vec3.ZERO;public double distanceToSqr(net.minecraft.world.phys.Vec3 p){double x=position.x-p.x,y=position.y-p.y,z=position.z-p.z;return x*x+y*y+z*z;}public final int id;public final UUID uuid;public boolean alive=true,removed,spectator; public Entity(int i,UUID u){id=i;uuid=u;}public net.minecraft.world.phys.Vec3 position(){return position;}public int getId(){return id;}public UUID getUUID(){return uuid;}public boolean isAlive(){return alive;}public boolean isRemoved(){return removed;}public boolean isSpectator(){return spectator;}}
